get_search_settings.code:
var response = await client.SearchSettings.GetSearchSettingsAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var searchSettings = (IReadOnlyDictionary<string, object?>)body["search_settings"]!;
var searchFields = (IReadOnlyDictionary<string, object?>)searchSettings["search_fields"]!;
foreach (var field in ((IReadOnlyList<object?>)searchFields["fields"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{field["priority"]} {field["field"]}");

